A polynomial term is stored as (coefficient, exponent, next) in descending exponent order. Addition merges two sorted lists, combining equal powers and omitting zero coefficients.

Complete ISO C example:
#include <stdio.h>
#include <stdlib.h>
typedef struct Node {
    int coef, exp;
    struct Node *next;
} Node;
void append(Node **head, Node **tail, int coef, int exp) {
    if (coef == 0) return;
    Node *n = malloc(sizeof *n);
    if (!n) { perror("malloc"); exit(1); }
    n->coef=coef; n->exp=exp; n->next=NULL;
    if (*tail) (*tail)->next=n; else *head=n;
    *tail=n;
}
Node *add(const Node *a, const Node *b) {
    Node *head=NULL,*tail=NULL;
    while (a && b) {
        if (a->exp == b->exp) {
            append(&head,&tail,a->coef+b->coef,a->exp);
            a=a->next; b=b->next;
        } else if (a->exp > b->exp) {
            append(&head,&tail,a->coef,a->exp); a=a->next;
        } else {
            append(&head,&tail,b->coef,b->exp); b=b->next;
        }
    }
    while (a) { append(&head,&tail,a->coef,a->exp); a=a->next; }
    while (b) { append(&head,&tail,b->coef,b->exp); b=b->next; }
    return head;
}
void printPoly(const Node *p) {
    if (!p) { puts("0"); return; }
    for (;p;p=p->next)
        printf("%+dx^%d%s",p->coef,p->exp,p->next?" ":"\n");
}
void freePoly(Node *p) { while(p) { Node *t=p;p=p->next;free(t); } }
int main(void) {
    Node *a=NULL,*at=NULL,*b=NULL,*bt=NULL;
    append(&a,&at,4,3); append(&a,&at,2,1); append(&a,&at,5,0);
    append(&b,&bt,3,2); append(&b,&bt,7,1); append(&b,&bt,-5,0);
    Node *sum=add(a,b);
    printPoly(sum); /* +4x^3 +3x^2 +9x^1 */
    freePoly(a);freePoly(b);freePoly(sum);
    return 0;
}

Complexity: O(m+n) time for m and n terms, O(m+n) output space.

A linked queue stores head/front and tail/rear pointers; enqueue inserts at rear, dequeue removes at front. Time O(1) for either operation.

Complete C example:
#include <stdio.h>
#include <stdlib.h>
typedef struct Node { int value; struct Node *next; } Node;
static Node *front=NULL,*rear=NULL;
void insert(int x) {
    Node *n=malloc(sizeof *n);
    if(!n) { perror("malloc"); exit(1); }
    n->value=x; n->next=NULL;
    if(rear) rear->next=n; else front=n;
    rear=n;
}
int delete(int *out) {
    if(!front) return 0;
    Node *old=front;
    *out=old->value;
    front=front->next;
    if(!front) rear=NULL;
    free(old);
    return 1;
}
void print(void) {
    for(Node *p=front;p;p=p->next) printf("%d ",p->value);
    putchar('\n');
}
int main(void) {
    int x;
    insert(10);insert(20);insert(30);print();
    if(delete(&x)) printf("Deleted: %d\n",x);
    print();
    while(delete(&x)) {}
    return 0;
}

A simple fixed-capacity linear array queue can waste vacant cells at the front when rear reaches the array end. A circular array queue wraps front and rear modulo capacity to reuse those cells. A linked queue doesn't have that specific limitation.

Use a stack to store opening brackets and pop/check on each closing bracket.

Complete C program:
#include <stdio.h>
#include <string.h>
int balanced(const char *s) {
    char st[1000];
    int top=-1;
    for(size_t i=0;s[i]!='\0';i++) {
        char c=s[i];
        if(c=='('||c=='['||c=='{') {
            if(top==999) return 0;
            st[++top]=c;
        } else if(c==')'||c==']'||c=='}') {
            if(top<0) return 0;
            char open=st[top--];
            if(!((open=='('&&c==')') ||
                 (open=='['&&c==']') ||
                 (open=='{'&&c=='}'))) return 0;
        }
    }
    return top==-1;
}
int main(void) {
    char expr[1000];
    if(!fgets(expr,sizeof expr,stdin)) return 1;
    puts(balanced(expr)?"Balanced":"Not balanced");
    return 0;
}
Example input: {[()]} -> Balanced. Complexity O(n) time and O(n) stack space (bounded by this implementation's 1000-char limit).
